package app.officinalibri;
import org.junit.*;import org.junit.rules.TemporaryFolder;import org.json.*;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;import static org.junit.Assert.*;
public class MobileStoreTest {
 @Rule public TemporaryFolder temp=new TemporaryFolder();
 private MobileStore store()throws Exception{return new MobileStore(temp.newFolder());}
 private JSONObject fresh()throws Exception {String id=UUID.randomUUID().toString();return new JSONObject().put("project",new JSONObject().put("id",id).put("title","Romanzo sintetico").put("kind","romanzo")).put("novel",new JSONObject().put("projectId",id).put("revision",0).put("sections",new JSONArray()));}
 @Test public void createSaveConflictReopenAndRestore()throws Exception {MobileStore store=store();JSONObject state=store.create(fresh());String id=state.getString("id");JSONObject n=state.getJSONObject("novel");n.put("textFixture","Aggiornato");JSONObject saved=store.save(id,n);assertEquals(1,saved.getInt("revision"));assertEquals("Aggiornato",new MobileStore(store.books.getParentFile()).read(id).getJSONObject("novel").getString("textFixture"));try{store.save(id,new JSONObject(n.toString()).put("revision",0));fail();}catch(IOException expected){}String snapshot=store.history(id).getString(0);JSONObject restored=store.restore(id,snapshot,1);assertFalse(restored.has("textFixture"));assertEquals(2,restored.getInt("revision"));assertEquals(2,store.history(id).length());}
 @Test public void zipRoundTripPreservesSourceAndIndependentCopy()throws Exception {MobileStore store=store();JSONObject state=store.create(fresh());String id=state.getString("id");File resource=new File(store.folder(id),"assets/"+"a".repeat(64)+".png");Files.createDirectories(resource.getParentFile().toPath());Files.write(resource.toPath(),new byte[]{1,2,3});ByteArrayOutputStream bytes=new ByteArrayOutputStream();store.exportArchive(id,bytes);JSONObject imported=store.importArchive(new ByteArrayInputStream(bytes.toByteArray()));assertNotEquals(id,imported.getString("id"));assertEquals(1,store.list().length());store.accept(imported.getString("id"));assertEquals(2,store.list().length());assertArrayEquals(new byte[]{1,2,3},Files.readAllBytes(new File(store.folder(imported.getString("id")),"assets/"+resource.getName()).toPath()));}
 @Test public void unsafeArchiveCannotEscapeStaging()throws Exception {MobileStore store=store();ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(bytes)){zip.putNextEntry(new ZipEntry("../fuori.txt"));zip.write(new byte[]{1});zip.closeEntry();}try{store.importArchive(new ByteArrayInputStream(bytes.toByteArray()));fail();}catch(IOException expected){}assertFalse(new File(store.staging.getParentFile(),"fuori.txt").exists());assertEquals(0,store.list().length());assertEquals(0,Objects.requireNonNull(store.staging.list()).length);}
 @Test public void incorrectInventoryIsRejected()throws Exception {MobileStore store=store();JSONObject state=store.create(fresh());ByteArrayOutputStream bytes=new ByteArrayOutputStream();store.exportArchive(state.getString("id"),bytes);Map<String,byte[]> entries=new LinkedHashMap<>();try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(bytes.toByteArray()))){ZipEntry entry;while((entry=zip.getNextEntry())!=null){entries.put(entry.getName(),zip.readAllBytes());zip.closeEntry();}}entries.put("romanzo.json","{}".getBytes());ByteArrayOutputStream bad=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(bad)){for(Map.Entry<String,byte[]> entry:entries.entrySet()){zip.putNextEntry(new ZipEntry(entry.getKey()));zip.write(entry.getValue());zip.closeEntry();}}try{store.importArchive(new ByteArrayInputStream(bad.toByteArray()));fail();}catch(IOException expected){}assertEquals(1,store.list().length());}
 @Test public void desktopFixtureEditedAndExportedForDesktop()throws Exception {MobileStore store=store();File fixture=new File(System.getProperty("officina.fixture"));assertTrue("Generare prima la fixture con node --test tests/portable.test.mjs",fixture.isFile());JSONObject state=store.importArchive(new FileInputStream(fixture));state=store.accept(state.getString("id"));String id=state.getString("id");JSONObject n=state.getJSONObject("novel"),section=n.getJSONArray("sections").getJSONObject(0),run=section.getJSONArray("paragraphs").getJSONObject(0).getJSONArray("runs").getJSONObject(0);run.put("text",run.getString("text")+" modificato da Android nativo");section.put("text",section.getString("text").replace("Inizio","Inizio modificato da Android nativo"));JSONObject saved=store.save(id,n);assertEquals(2,saved.getInt("revision"));File out=new File(System.getProperty("officina.output"));Files.createDirectories(out.getParentFile().toPath());store.exportArchive(id,new FileOutputStream(out));assertTrue(out.length()>1000);assertTrue(state.getJSONArray("fontFiles").length()>0);}
 @Test public void checkpointThrottleKeepsLatestDocumentWithoutDeletingHistory()throws Exception {MobileStore store=store();JSONObject state=store.create(fresh());String id=state.getString("id");JSONObject n=store.save(id,state.getJSONObject("novel"),false);for(int i=0;i<4;i++)n=store.save(id,n,false);assertEquals(5,n.getInt("revision"));assertEquals(1,store.history(id).length());store.save(id,n,true);assertEquals(2,store.history(id).length());}
 @Test public void firstEditAfterImportAlwaysKeepsAnOriginalCheckpoint()throws Exception {MobileStore store=store();JSONObject state=store.create(fresh());String original=state.getString("id");store.save(original,state.getJSONObject("novel"));ByteArrayOutputStream bytes=new ByteArrayOutputStream();store.exportArchive(original,bytes);JSONObject copy=store.importArchive(new ByteArrayInputStream(bytes.toByteArray()));copy=store.accept(copy.getString("id"));String id=copy.getString("id");assertEquals(1,store.history(id).length());store.save(id,copy.getJSONObject("novel"),false);assertEquals(2,store.history(id).length());}
}
